module hall_students (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] num0,\n    input [7:0] num1,\n    input [7:0] num2,\n    input [7:0] num3,\n    output reg [7:0] result,\n    output reg done\n);\n\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n    reg [1:0] state;\n    reg [7:0] cnt_temp;\n\n    function [7:0] gcd_comb;\n        input [7:0] a;\n        input [7:0] b;\n        reg [7:0] x,y,temp;\n        reg done_flag;\n        integer i;\n        begin\n            x = a;\n            y = b;\n            done_flag = 1'b0;\n            for (i=0; i<8; i=i+1) begin\n                if (!done_flag) begin\n                    if (y == 8'd0) begin\n                        done_flag = 1'b1;\n                    end\n                    else begin\n                        temp = y;\n                        y = x % y;\n                        x = temp;\n                    end\n                end\n            end\n            gcd_comb = x;\n        end\n    endfunction\n\n    function [7:0] compute_count;\n        input [7:0] n0,n1,n2,n3;\n        reg [7:0] g01,g02,g03,g12,g13,g23;\n        reg [5:0] allowed;\n        reg [7:0] cnt;\n        begin\n            g01 = gcd_comb(n0, n1);\n            g02 = gcd_comb(n0, n2);\n            g03 = gcd_comb(n0, n3);\n            g12 = gcd_comb(n1, n2);\n            g13 = gcd_comb(n1, n3);\n            g23 = gcd_comb(n2, n3);\n\n            allowed = {\n                g23 > 8'd1,\n                g13 > 8'd1,\n                g12 > 8'd1,\n                g03 > 8'd1,\n                g02 > 8'd1,\n                g01 > 8'd1\n            };\n\n            cnt = 8'd0;\n            if ((allowed & 6'b000111) == 6'b000111) cnt = cnt + 8'd1;\n            if ((allowed & 6'b100011) == 6'b100011) cnt = cnt + 8'd1;\n            if ((allowed & 6'b001101) == 6'b001101) cnt = cnt + 8'd1;\n            if ((allowed & 6'b100101) == 6'b100101) cnt = cnt + 8'd1;\n            if ((allowed & 6'b011001) == 6'b011001) cnt = cnt + 8'd1;\n            if ((allowed & 6'b101001) == 6'b101001) cnt = cnt + 8'd1;\n            if ((allowed & 6'b110001) == 6'b110001) cnt = cnt + 8'd1;\n            if ((allowed & 6'b001110) == 6'b001110) cnt = cnt + 8'd1;\n            if ((allowed & 6'b101010) == 6'b101010) cnt = cnt + 8'd1;\n            if ((allowed & 6'b011100) == 6'b011100) cnt = cnt + 8'd1;\n            if ((allowed & 6'b101100) == 6'b101100) cnt = cnt + 8'd1;\n            if ((allowed & 6'b110100) == 6'b110100) cnt = cnt + 8'd1;\n\n            compute_count = cnt;\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            cnt_temp <= 8'd0;\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cnt_temp <= 8'd0;\n                    if (start) state <= COMPUTE;\n                end\n\n                COMPUTE: begin\n                    result <= compute_count(num0, num1, num2, num3);\n                    state <= FINISH;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule